def fitm(f,p0,n=8):
    best=None
    for s in range(n):
        x0=np.array(p0,float)*(1+0.2*np.random.randn(len(p0))) if s else np.array(p0,float)
        try:
            r=least_squares(lambda p: f(p)-dP_dt, x0, max_nfev=4000)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    return np.mean((f(best.x)-dP_dt)**2)/var, np.round(best.x,5)
